import java.util.*;

class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {
        Set<Integer> values = new HashSet<>();
        for (int num : nums) {
            values.add(num);
        }

        int count = 0;
        for (int num : nums) {
            if (values.contains(num + diff) && values.contains(num + 2 * diff)) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {
        boolean[] present = new boolean[201];
        for (int num : nums) {
            present[num] = true;
        }

        int count = 0;
        for (int num : nums) {
            if (num + 2 * diff < present.length
                    && present[num + diff]
                    && present[num + 2 * diff]) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {
        int n = nums.length;
        int middle = 0;
        int end = 0;
        int count = 0;

        for (int start = 0; start < n; start++) {
            while (middle < n && nums[middle] - nums[start] < diff) {
                middle++;
            }
            while (end < n && nums[end] - nums[start] < 2 * diff) {
                end++;
            }
            if (middle < n && end < n
                    && nums[middle] - nums[start] == diff
                    && nums[end] - nums[start] == 2 * diff) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                for (int k = j + 1; k < nums.length; k++) {
                    if (nums[j] - nums[i] == diff && nums[k] - nums[j] == diff) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}
